class Step(NamedTuple):
    """道筋(`a[].b`)の 1 段。`key` はキー、`is_each` は配列の各要素へ進むか、`where` は起点からそのキーまでの綴り。"""

    key: str
    is_each: bool
    where: str

    def item_where(self, index: int) -> str:
        """配列の `index` 番目の要素までの綴り。"""
        return f"{self.where}[{index}]"


def step_of(step: str, where: str) -> Step:
    """道筋の 1 段を読む(`[]` で終わる段は配列の各要素へ進む)。

    @param where 起点からその段の手前までの綴り
    """
    key = step.removesuffix("[]")
    return Step(key, step.endswith("[]"), f"{where}.{key}" if where else key)

const matchAt = (pattern, cursor) => {
  pattern.lastIndex = cursor.at;
  const match = pattern.exec(cursor.text);
  return match ? match[0] : null;
};

/** JSX のタグ名。`.` `:` `-` でつないだもの(`Foo.Bar` / `svg:path` / `my-element`)も 1 つの名前にする。 */
const JsxName = String.raw`${JsIdentifier.source}(?:[.:-][\w$]+)*`;
/** JSX のタグの `<` と名前(`<名前` / `</名前`)と、フラグメントの `<>` / `</>`。 */
const JsxTag = new RegExp(String.raw`</?(?:${JsxName}|>)`, "y");
/** JSX の属性名。`-` `:` でつないだもの(`aria-label` / `xlink:href`)も 1 つの名前にする。HTML の `AttributeName` と同じく、値の無い属性もキーにする。 */
const JsxAttributeName = new RegExp(String.raw`${JsIdentifier.source}(?:[-:][\w$]+)*`, "y");
/** JSX の子の中の本文。タグの `<` と式の `{` の手前まで。 */
const JsxText = /[^<{]+/y;
/** JSX の自己閉じの `/>`。`/` と `>` の間に空白があってもよい。 */
const JsxSelfClosing = /\/\s*>/y;
/**
 * `.tsx` で TypeScript が総称の矢印関数の型引数として読む形。`<` の後の名前(前に `const` があってもよい)に `,` か `=` が続くか、
 * `extends` が続いてその後が `=` `>` `/` でないもの。`=` に `==` `=>` を、`/` に `/=` を含めないのは TypeScript の字句に合わせる。
 * TypeScript と違い、字句の間のコメントは飛ばさない(名前と `,` の間にコメントがあるとタグと読む)。
 */
const ArrowTypeParameters = new RegExp(String.raw`<\s*(?:const\s+)?${JsIdentifier.source}(?![\w$])\s*(?:,|=(?![=>])|extends\b(?!\s*(?:=(?![=>])|>|\/(?!=))))`, "y");

/**
 * 行の各位置から先で最初に来る `{` `;` `}`。CSS の宣言の判定が語ごとに行末まで探し直さないよう、行ごとに 1 度だけ求める。
 * @returns 位置ごとの字(その位置から先に無ければ空文字)
 */
const declarationStopsOf = (text) => {
  const stops = new Array(text.length);
  let next = "";
  for (let index = text.length - 1; index >= 0; index -= 1) {
    if (DeclarationStops.has(text[index])) next = text[index];
    stops[index] = next;
  }
  return stops;
};

/** CSS で、位置から始まる `:` が宣言の区切りか。`:` の後が空白か行末、または後で最初に来る `{` `;` `}` が `;` か `}` なら宣言(`a:hover {` はセレクタ)。 */
const isDeclarationColonAt = (cursor, from) => {
  const after = from + matchAt(CssColon, { text: cursor.text, at: from }).length;
  const next = cursor.text[after];
  const isSpaceAfter = next === undefined || /\s/.test(next);
  const stop = cursor.declarationStops[after];
  return isSpaceAfter || stop === ";" || stop === "}";
};

// 丸括弧・角括弧の中(`@media (max-width: …)`・属性セレクタ)と、`:` の直後の名前はプロパティにしない。
const isDeclarationPlace = cursor.bracket !== "(" && cursor.bracket !== "[" && cursor.prevSolid !== ":";
const property = isDeclarationPlace ? matchAt(CssPropertyName, cursor) : null;
const isProperty = property !== null && isDeclarationColonAt(cursor, cursor.at + property.length);
if (isProperty) return Token("tok-key", property);

/**
 * 式が始まる位置にある JSX のタグ(開きタグ・閉じタグ・フラグメント)。総称の矢印関数の型引数ならタグにしない。
 *
 * 読み始めを誤ると、後ろを JSX(属性名か本文)として読み、誤って開いた要素を閉じる閉じタグか `/>` まで JS / TS へ戻らない。型の位置の
 * 総称の関数型(`=` `{` `:` `,` `(` `|` `&` `=>` の後の `<T>(`)と、前の行の値に続く行頭の `<`(`a` の次の行の `<b`)はタグと読む。
 * `<` の直後に空白のあるタグ(`< div>`)は、タグと読まない。
 */
const jsxTagInExpressionAt = (cursor) => {
  const isTagPlace = isExpressionPlace(cursor) && matchAt(ArrowTypeParameters, cursor) === null;
  return isTagPlace ? jsxTagAt(cursor) : null;
};

def _heredoc_after(line: str, region: Region | None) -> Region | None:
    """行を読み終えた後に開いているヒアドキュメント。"""
    if region is not None:
        closing = line.lstrip("\t") if region.strips_tabs else line
        return None if closing == region.name else region
    match = HeredocStart.search(line)
    is_known = match is not None and match.group(3) in HeredocDelimiters
    if not is_known:
        return None
    return Region(line, match.group(3), match.group(1) == "-")

