create: ({ topics, emptySide }) => {
  let current = topics.length === 0 ? null : 0;
  let shownCurrent = null;
  const side = el("div", { class: "side" });
  const inlineHolders = topics.map(() => el("div", { class: "side" }));
  const articles = topics.map((topic, index) => el("article", { class: "topic", ...topic.attributes }, [
    headOf(topic),
    el("details", { class: "topic-inline" }, [el("summary", { text: topic.inlineSummary }), inlineHolders[index]]),
    ...topic.body,
  ]));

  const render = () => {
    for (const [index, row] of tocRows.entries()) row.classList.toggle("is-current", index === current);
    for (const [index, holder] of inlineHolders.entries()) holder.replaceChildren(...topics[index].sideBlocksOf());
    side.replaceChildren(...(current === null ? [el("p", { class: "side-note", text: emptySide })] : [sideHeadOf(topics[current]), ...topics[current].sideBlocksOf()]));
    if (current !== shownCurrent) side.scrollTop = 0;
    shownCurrent = current;
  };

  /**
   * 節へ送る。今の節はスクロールを待たずにその節にする。
   *
   * 今の節が同じでも描き直す(`showMention` が選び直したマスの根拠を、ここで描かせるため)。
   */
  const sendTo = (index) => {
    current = index;
    render();
    articles[index].scrollIntoView({ block: "start" });
  };
  const tocRows = topics.map((topic, index) => pressable("button", { class: "row plain-button" }, tocPartsOf(topic), () => sendTo(index)));
  const tocItems = topics.flatMap((topic, index) => [...(topic.tocDivider === null ? [] : [el("div", { class: "topic-toc-divider", text: topic.tocDivider })]), tocRows[index]]);
  const toc = el("div", { class: "panel-scroll" }, tocItems.length > 0 ? tocItems : [emptyOf("節がありません。")]);

  /**
   * スクロールに合わせて今の節を決め直す。変わったときだけ描き直す。
   * @param top スクロールしている領域の上端の、表示領域の上端からの距離
   */
  const follow = (top) => {
    const next = TopicScroll.currentOf(articles.map((article) => article.getBoundingClientRect().top - top));
    if (next === current) return;
    current = next;
    render();
  };

  render();
  return { articles, toc, inlineHolders, side, follow, sendTo, render };
},

subscribe: ({ main, follow }) => {
  const isShown = () => {
    const screen = main.closest(".screen");
    return screen !== null && !screen.hidden;
  };
  // スクロールしているのが本文の欄(広い幅)かページ全体(狭い幅)かは CSS の `@media` が決めるので、イベントの出どころで見分ける。
  main.addEventListener("scroll", () => follow(main.getBoundingClientRect().top), { passive: true });
  // ページ全体のスクロールは、その画面が隠れているあいだはほかの画面のものなので見ない。
  window.addEventListener("scroll", () => {
    if (isShown()) follow(0);
  }, { passive: true });
},

return Object.freeze({
  Routes,
  Required,
  /**
   * ページが組み立てに使う形を見る。
   * @returns 型の違う道筋か、必須のキー(`Required`)が欠けた道筋(`impact.tables[].outcomes` の形)。崩れが 2 か所以上なら最も外側のもの。
   *   崩れていなければ null
   */
  problemOf: (explain) => {
    const mistyped = Routes.filter(([route, kind]) => valuesAt(explain, route.split(".")).some((value) => !ShapeKinds[kind](value))).map(([route]) => route);
    const lacking = Required.filter((required) => lacks(explain, required)).map(({ route }) => route);
    const broken = [...mistyped, ...lacking];
    if (broken.length === 0) return null;
    return broken.reduce((outer, candidate) => (depthOf(candidate) < depthOf(outer) ? candidate : outer));
  },
});

// 欠けていれば崩れとする道筋。primers・terms の下の必須のキーのうち、値が文(text)か 1 つのオブジェクト(record)のもの。
// `kinds` は、手前のオブジェクトが kind で持つキーの決まるもの(Variant)なら、そのキーを必須とする kind の並びで、それ以外の
// kind のオブジェクトには求めない。kind に依らないオブジェクト(Shape)なら null で、どれにも求める。Shapes と Variants から
// 導いたものと同じ並びで、`pr-explain-core-cases.sh` が突き合わせる。配列は欠けても `listOf` が空として読むので入れない。
const Required = Object.freeze([
  { route: "primers[].category", kinds: ["language", "codebase"] },
  { route: "primers[].label", kinds: ["language", "codebase"] },
  { route: "primers[].gist", kinds: ["language", "codebase"] },
  { route: "primers[].passages[].text", kinds: ["text", "caution", "memo", "rule", "spec", "history"] },
  { route: "primers[].passages[].code", kinds: ["declaration"] },
  { route: "primers[].passages[].parameters[].name", kinds: null },
  { route: "primers[].passages[].parameters[].type", kinds: null },
  { route: "primers[].passages[].parameters[].text", kinds: null },
  { route: "primers[].passages[].excerpt", kinds: ["excerpt"] },
  { route: "primers[].passages[].excerpt.path", kinds: null },
  { route: "primers[].occurrences[].path", kinds: null },
  { route: "primers[].occurrences[].text", kinds: null },
  { route: "terms[].label", kinds: null },
  { route: "terms[].text", kinds: null },
]);

/** 技術の手引きの本文に書く用語の印 `[[表示|用語の id]]`。 */
const TermMarks = (() => {
  // 綴りは `build-pr-explain.py` の `TermMarkPattern` と同じで、`pr-explain-core-cases.sh` が突き合わせる。
  const Pattern = /\[\[([^\[\]|]+)\|([A-Za-z0-9][A-Za-z0-9_-]{0,63})\]\]/g;
  // 印を読む道筋。`build-pr-explain.py` の `routes_with(MarkedText)` と同じ綴り・同じ並びで、`pr-explain-core-cases.sh` が突き合わせる。
  const Routes = Object.freeze(["primers[].gist", "primers[].passages[].text", "primers[].passages[].parameters[].text"]);
  // 節の中の道筋(`primers[].` を外し、段に割ったもの)。
  const InPrimer = Routes.map((route) => route.replace(/^primers\[\]\./, "").split("."));

def has_stray_brackets(value: str) -> bool:
    """`` ` `` の外に、印になっていない `[[` / `]]` があるか。ページは印の外の切れ端ごとに `` ` `` を対にするので、切れ端ごとに見る。"""
    outside_code = [part for piece in plain_pieces_of(value) for is_code, part in code_spans_of(piece) if not is_code]
    return any("[[" in part or "]]" in part for part in outside_code)


def has_mark_in_code(value: str) -> bool:
    """`` ` `` の中に印の形を書いたか。印の始まりより前にある、印の外の `` ` `` が奇数なら、書き手はコードの中に書いている。"""
    plains = plain_pieces_of(value)
    ticks_before = [sum(piece.count("`") for piece in plains[:index + 1]) for index in range(len(plains) - 1)]
    return any(count % 2 == 1 for count in ticks_before)


def is_marked_text(value: object) -> bool:
    """空でない文字列で、用語の印の 2 つの規則(`has_stray_brackets` / `has_mark_in_code`)のどちらにも当たらないか。"""
    return is_text(value) and not has_stray_brackets(value) and not has_mark_in_code(value)

create: (text) => {
  const parts = text.split("`");
  const hasUnclosed = parts.length % 2 === 0;
  const paired = hasUnclosed ? [...parts.slice(0, -2), `${parts[parts.length - 2]}\`${parts[parts.length - 1]}`] : parts;
  return paired.map((part, index) => ({ isCode: index % 2 === 1, text: part }));
},

const topicOf = (primer, { termAt, positionAt, testAt, flows, reachOf }) => {
  const marked = TermMarks.withPieces(primer);
  const resolve = (pieces) => resolvedPiecesOf(pieces, termAt);
  return {
    id: primer.id,
    kind: primer.kind,
    category: primer.category,
    label: primer.label,
    gist: resolve(marked.gist),
    passages: listOf(marked.passages).flatMap((passage) => passagesOf(passage, resolve)),
    occurrences: listOf(primer.occurrences).map((occurrence) => occurrenceOf(occurrence, reachOf)),
    seeAlso: valuesIn(positionAt, primer.seeAlso),
    terms: valuesIn(termAt, TermMarks.termIdsOf(marked)),
    status: statusOf(primer),
    tests: testEvidenceOf(primer.tests, testAt),
    flows: valuesIn(flows, primer.flows),
  };
};

/** タブの節と用語集。用語集は、節の用語を最初に出た順に重複なくつなぐ(1 つも無ければ null)。 */
const tabOf = (topics) => {
  const terms = [...new Map(topics.flatMap((topic) => topic.terms).map((term) => [term.id, term])).values()];
  return { topics, glossary: terms.length === 0 ? null : { terms } };
};

/**
 * 最初に開くタブ。
 * @param primerTopics `create` が返した、書かれている技術の手引き
 * @returns 言語・フレームワークに節があればそれ、無くてこの PR の実装にあればそれ。どちらにも無ければ言語・フレームワーク
 */
firstTabOf: (primerTopics) => {
  const hasLanguage = primerTopics.tabs[PrimerKinds.Language].topics.length > 0;
  const hasOnlyCodebase = !hasLanguage && primerTopics.tabs[PrimerKinds.Codebase].topics.length > 0;
  return hasOnlyCodebase ? PrimerKinds.Codebase : PrimerKinds.Language;
},

/**
 * 出てくる場所の 1 つの sha が、変更の経緯のどこまで届くかを決める関数を作る。
 * @param commits 地図のコミット(古い順)
 * @param explainedAt 解説の sha が地図のコミットの何番目か(無ければ -1)
 * @returns `{sha, path, lineRange}` を受け取り、届き方を返す関数。地図に無い sha は `unmapped`、マージコミットは `merge`、
 *   そのコミットが `path` のファイルを変えていなければ `untouched`。行まで(`line`)届くのは、`lineRange` があり、そのコミットが
 *   解説の sha 以前で、あいだ(解説の sha を含む)にマージコミットも `path` を変えたコミットも無いときだけで、ほかは `file`
 */
const reachOfIn = (commits, explainedAt) => ({ sha, path, lineRange }) => {
  const index = commits.findIndex((commit) => commit.sha === sha);
  if (index < 0) return { kind: "unmapped" };
  const commit = commits[index];
  if (commit.merge) return { kind: "merge" };
  if (!commit.files.some((file) => file.path === path)) return { kind: "untouched" };
  const shiftsLines = (later) => later.merge || later.files.some((file) => file.path === path || file.oldPath === path);
  const isLatestChange = index <= explainedAt && !commits.slice(index + 1, explainedAt + 1).some(shiftsLines);
  const reachesLine = lineRange !== null && isLatestChange;
  return reachesLine ? { kind: "line", lineRange } : { kind: "file" };
};

/** 出てくる場所の 1 つの sha の、ボタンの名前と押したときの移り先。届かない sha は、何が起きるかの注意(`warning`)を添える。 */
const destinationOf = ({ sha, reach }, path) => {
  const toCommit = () => go.toCommit(sha);
  switch (reach.kind) {
    case "line":
    case "file":
      return { label: "差分で見る", onPress: () => go.toCommitFile({ sha, path, lineRange: reach.kind === "line" ? reach.lineRange : null }), warning: null };
    case "untouched":
      return { label: "コミットを見る", onPress: toCommit, warning: "このコミットは、このパスのファイルを変えていません。当時は別のパスだったのかもしれません(コミットの先頭を開きます)" };
    case "merge":
      return { label: "コミットを見る", onPress: toCommit, warning: "マージコミットなので差分がありません(コミットの先頭を開きます)" };
    case "unmapped":
      return { label: "ブランチ全体の流れを見る", onPress: toCommit, warning: "変更の地図に無いコミットなので差分がありません(ブランチ全体の流れを開きます)" };
  }
};
const destinationNodesOf = (destination, path) => {
  const { label, onPress, warning } = destinationOf(destination, path);
  const link = commitLinkOf({ sha: destination.sha, label, commitAt: explained.commitAt, onPress });
  return [link, ...(warning === null ? [] : [el("span", { class: "warn-text", text: warning })])];
};

def fields_of(rule: Shape | Variant) -> dict[str, Field]:
    """オブジェクトの規則が持つキー。Variant は kind のキーを kind の順に合わせる(同じキーは kind をまたいで同じ規則)。"""
    if isinstance(rule, Shape):
        return Shapes[rule.name]
    return {key: field for fields in Variants[rule.name].values() for key, field in fields.items()}


def routes_under(rule: object, route: str) -> list[tuple[str, object, bool]]:
    """規則の下にある道筋を、外側から書いた順に集める(`Shapes` と `Variants` を辿る)。判定表と、印・抜粋の道筋を導く検査
    (`term_mark_problems`・`with_read_excerpts`)が使う。

    @param rule `Field` の `value` に書く規則
    @param route その規則の道筋(`impact` など)。配列の中へ進む段には `[]` を付ける
    @returns `(道筋, 配列なら要素の規則, 配列か)` の並び
    """
    is_many = isinstance(rule, Many)
    inner = rule.item if is_many else rule
    if not isinstance(inner, (Shape, Variant)):
        return [(route, inner, is_many)]
    prefix = f"{route}[]" if is_many else route
    nested = [found for key, field in fields_of(inner).items() for found in routes_under(field.value, f"{prefix}.{key}")]
    return [(route, inner, is_many), *nested]


def routes_with(rule: object) -> list[str]:
    """解説(Explain)の下で、規則が `rule` の道筋を、外側から書いた順に集める。配列なら要素の規則で見る。"""
    return [route for key, field in Shapes["Explain"].items() for route, inner, _ in routes_under(field.value, key) if inner == rule]

/** 抜粋の行。 */
const ExcerptRows = Object.freeze({
  /**
   * 抜粋の行を、ファイルの行番号と強調の有無と字句にする。
   *
   * 強調の要素がオブジェクトかどうかは、骨組みの検査が見ている。start / end が数でなくても組み立ては落ちない(どの行が強調に
   * なるかは比較の型変換しだい。数かどうかは解説の検査が落とす)。
   * @param excerpt 中身(`text`)と、あれば開いた行(`openingLine`)を足した抜粋
   * @returns `{number, text, isEmphasized, tokens}` の並び。`number` は抜粋の `start` から数え、強調を省けばどの行も強調しない。
   *   `tokens` は 1 行目から読み進めた字句で、開いた行が文字列ならその埋め込みの中から読み始める
   */
  create: (excerpt) => {
    const emphasis = listOf(excerpt.emphasis);
    const grammar = Tokenizer.grammarOf(excerpt.path);
    const texts = excerpt.text.split("\n");
    const read = Tokenizer.tokenizeLines(texts, grammar, Tokenizer.startAfter(isString(excerpt.openingLine) ? excerpt.openingLine : null, grammar));
    return texts.map((text, index) => {
      const number = excerpt.start + index;
      return { number, text, isEmphasized: emphasis.some((span) => isWithin(number, span)), tokens: read[index].tokens };
    });
  },
});

/**
 * コードの抜粋の箱。行番号はファイルの行で、強調の範囲に入る行には `is-emphasized` を付ける。
 * @param excerpt 抜粋(検査が中身の `text` と、あれば開いた行 `openingLine` を足したもの)
 * @returns 箱 1 つの並び。中身(`text`)が足されていなければ空の並び
 */
const excerptBoxesOf = (excerpt) => {
  if (!isString(excerpt.text)) return [];
  const rows = ExcerptRows.create(excerpt).map((row) => el("div", { class: classesOf("excerpt-line", { "is-emphasized": row.isEmphasized }) }, [el("span", { class: "ln", text: String(row.number) }), codeTextOf(row.tokens)]));
  return [el("div", { class: "excerpt" }, rows)];
};

/**
 * テストの画面のコードの抜粋。小見出しの横に `パス:開始-終了` を出す。
 * @param title 小見出し
 * @returns 中身(`text`)が足されていなければ空の並び
 */
const excerptBlockOf = (excerpt, title) => excerptBoxesOf(excerpt).map((box) => el("div", { class: "side-block" }, [eyebrowOf(title, `${excerpt.path}:${excerpt.start}-${excerpt.end}`), box]));

/**
 * 技術の手引きのコード例。箱の上端に、パス · 行番号と、拡張子(言語名の代わり)の見出しを置く。
 * @returns 中身(`text`)が足されていなければ空の並び
 */
const codeExampleOf = (excerpt) => excerptBoxesOf(excerpt).map((box) => {
  const lines = excerpt.start === excerpt.end ? `L${excerpt.start}` : `L${excerpt.start}–${excerpt.end}`;
  const extension = (excerpt.path.match(/\.(\w+)$/) || [])[1] ?? "";
  return el("div", { class: "primer-code" }, [
    el("div", { class: "primer-code-head" }, [el("span", { class: "primer-code-path", text: `${excerpt.path} · ${lines}` }), el("span", { text: extension })]),
    box,
  ]);
});

/**
 * 途中の行から読み始めるときの持ち越し。開いた行を何も開いていない状態から読み、埋め込みだけを残す。
 * 括弧とタグの段(`brackets`)は持ち越さないので、hunk・抜粋が開きタグや JSX の子の途中から始まると、段の外(JSX は JS / TS、
 * HTML は本文)として読み始める。
 * @param openingLine 読み始める行の頭で効いている埋め込みを開いた行(検査の `openingLine` / 地図の `hunkOpeningLines`)。無ければ null
 * @param grammar ファイルの文法(`grammarOf`。null の文法はどの行でも埋め込みを開かない)
 * @returns 埋め込みだけを残した持ち越し。開いた行が null のとき・開いた行が埋め込みを開いていないときは、何も開いていない持ち越し
 */
startAfter: (openingLine, grammar) => {
  if (openingLine === null) return Start;
  const { region } = tokenizeLine(openingLine, grammar, Start).carry;
  return region === null ? Start : { ...Start, region };
},
/**
 * 続いた行を、前の行の持ち越しを次の行へ渡しながら字句に分ける。
 * @param texts 続いた行(改行を含まない)
 * @param grammar ファイルの文法(`grammarOf`)。null ならどの行も色の無い 1 字句
 * @param start 1 行目の頭の持ち越し(`startAfter` が返すもの)
 * @returns 行ごとの字句の並び(`tokens`)と、その行を読み終えた後の持ち越し(`carry`)。`texts` と同じ順
 */
tokenizeLines: (texts, grammar, start) => {
  const lines = [];
  let carry = start;
  for (const text of texts) {
    const read = tokenizeLine(text, grammar, carry);
    lines.push(read);
    carry = read.carry;
  }
  return lines;
},

/**
 * hunk の行を字句に分ける。変更前は `openingLines.old`、変更後は `openingLines.new` から読み始め、`-` の行は変更前だけ、`+` の
 * 行は変更後だけ、前後の行は両方で読み進める。
 * @param grammar ファイルの文法(`Tokenizer.grammarOf`)
 * @returns 行ごとの字句の並び(`hunk.lines` と同じ順)。前後の行は変更後の字句
 */
lineTokensOf: (hunk, grammar) => {
  const tokensBy = (lines, openingLine) => {
    const read = Tokenizer.tokenizeLines(lines.map((line) => line.text), grammar, Tokenizer.startAfter(openingLine, grammar));
    return new Map(lines.map((line, index) => [line, read[index].tokens]));
  };
  const before = tokensBy(hunk.lines.filter((line) => line.sign !== "+"), hunk.openingLines.old);
  const after = tokensBy(hunk.lines.filter((line) => line.sign !== "-"), hunk.openingLines.new);
  return hunk.lines.map((line) => after.get(line) ?? before.get(line));
},

/** 字句。`opens` は閉じずに行が終わった文字列・コメントの閉じ記号で、次の行の頭から続ける。 */
const Token = (cls, value, opens = null) => ({ cls, value, opens });

/**
 * 何も開いていない持ち越し。持ち越しは次の 3 つ。
 * - `open`: 閉じずに行が終わった文字列・コメント(`{cls, close}`)
 * - `region`: 中を別の言語で読んでいる埋め込み。null か、`{kind: "element", name}` / `{kind: "heredoc", delimiter, stripsTabs}`
 * - `brackets`: 開いたまま閉じていない括弧(`(` `[` `{`)と、HTML・`.tsx` / `.jsx` のタグの段(`TagLevels`)を、開いた順に並べた文字列
 *
 * JSX の段は括弧と交互に入れ子になる(`{ ( <li { …`)ので、別の並びにせず、開いて閉じる括弧と同じ並びに積む。
 */
const Start = Object.freeze({ open: null, region: null, brackets: "" });

/** 何も読んでいない位置の、直前の空白でない字(`prevSolid`。空文字は行頭)とその位置(`prevSolidAt`)と直前の語(`prevWord`)。 */
const Unread = Object.freeze({ prevSolid: "", prevSolidAt: -1, prevWord: "" });

/**
 * 字句を読んだ後の括弧の並び。色の無い字句だけを括弧として見る。
 *
 * 閉じ括弧は、一番上の開き括弧と種類が合うときだけ外し、合わなければ無視する。正規表現の文字クラスの `}` が、外側の `{` を
 * 閉じないため。正規表現の `\[` のように対にならない開き括弧は、並びに残ったままになる。
 */
const bracketsAfter = (brackets, token) => {
  if (token.cls !== null) return brackets;
  if (Openers.has(token.value)) return brackets + token.value;
  const isClosingTop = Object.hasOwn(Closers, token.value) && brackets.endsWith(Closers[token.value]);
  return isClosingTop ? brackets.slice(0, -1) : brackets;
};

let reading = readingFrom(region, 0);
// 埋め込みに入る・出るときは、中の言語を何も読んでいないところから読む。
const switchTo = (next) => {
  ({ open, region, brackets } = { ...Start, region: next });
  solid = Unread;
  reading = readingFrom(next, at);
};
while (at < text.length) {
  if (reading.closeAt === at) {
    switchTo(null);
    continue;
  }

def opening_lines(path: str, lines: list[str]) -> list[str | None]:
    """各行の頭で効いている埋め込みを開いた行。

    @param path ファイルのパス(拡張子で、要素とヒアドキュメントのどちらを読むかを決める)
    @param lines ファイルの行
    @returns 行ごとの開いた行。その行の頭で埋め込みの外にいる行と、埋め込みの無い拡張子のファイルの行は None
    """
    after = _element_after if path.endswith(ElementExtensions) else _heredoc_after if path.endswith(HeredocExtensions) else None
    if after is None:
        return [None] * len(lines)
    openings: list[str | None] = []
    region = None
    for line in lines:
        openings.append(None if region is None else region.line)
        region = after(line, region)
    return openings

def _element_after(line: str, region: Region | None) -> Region | None:
    """行を読み終えた後に開いている要素。"""
    for match in ElementTag.finditer(line):
        opens, closes = match.group(1), match.group(2)
        closes_region = closes is not None and region is not None and closes.lower() == region.name
        opens_new = opens is not None and region is None
        if opens_new:
            region = Region(line, opens.lower())
        elif closes_region:
            region = None
    return region

/** `.` の後の名前か。スプレッドの `...` の後は含めない。 */
const isMemberAt = (cursor) => cursor.prevSolid === "." && cursor.text[cursor.prevSolidAt - 1] !== ".";

/**
 * JS / TS のオブジェクトのキーか。`const x:`・`case foo:`・`ok ? left :`・丸括弧の中の `name:` はキーにしない。
 * 行頭の switch の `default:` もキーと区別できないので、キーとして色を付けない。
 */
const isKeyAt = (cursor, word, grammar) => {
  KeyAfter.lastIndex = cursor.at + word.length;
  const hasColon = grammar.objectKeys === true && KeyAfter.test(cursor.text);
  const followsKeyPlace = KeyFollows.has(cursor.prevSolid) || KeyModifiers.has(cursor.prevWord);
  return hasColon && followsKeyPlace && cursor.bracket !== "(";
};

/** 識別子の色。メンバー → キー → キーワード → 関数 → 型・変数の順に見る。 */
const identifierClassOf = (cursor, word, grammar) => {
  const isCall = cursor.text[cursor.at + word.length] === "(";
  const isMember = grammar.identifiers === true && isMemberAt(cursor);
  if (isMember) return isCall ? "tok-fn" : null;
  if (isKeyAt(cursor, word, grammar)) return null;
  if (grammar.keywords.has(word)) return "tok-kw";
  if (isCall) return "tok-fn";
  if (grammar.identifiers !== true) return null;
  const isType = /^[A-Z]/.test(word) || (grammar.types !== undefined && grammar.types.has(word));
  return isType ? "tok-type" : "tok-var";
};

/**
 * `.tsx` / `.jsx` で字句を読んだ後の、括弧と JSX の段の並び。タグは段を積み外しし、開きタグを閉じる `>` は子の段へ移り、
 * 自己閉じは段を外す。段の中では `{` だけを積み、段の外は `bracketsAfter` に渡す。
 *
 * 段の外で来た閉じタグ(要素の途中から読み始めた)は何も積まない。後ろが子か JS かは分からず、子として読むと `);` 以降を本文にしてしまうため。
 */
const jsxBracketsAfter = (brackets, token) => {
  const top = brackets.slice(-1);
  const outer = brackets.slice(0, -1);
  if (isTagToken(JsxTag, token)) {
    if (isClosingTag(token.value)) return top === TagLevels.Children ? outer : brackets;
    return brackets + (isFragment(token.value) ? TagLevels.Children : TagLevels.OpeningTag);
  }
  const closesOpeningTag = top === TagLevels.OpeningTag && token.value === ">";
  if (closesOpeningTag) return outer + TagLevels.Children;
  const selfCloses = top === TagLevels.OpeningTag && isWhole(JsxSelfClosing, token.value);
  if (selfCloses) return outer;
  // 本文の字句は `(` か `[` 1 文字だけにもなる(`<p>(</p>`)ので、JsxText では積むのを防げない。
  if (isTagLevel(top)) return token.value === "{" ? brackets + token.value : brackets;
  return bracketsAfter(brackets, token);
};

/**
 * HTML で字句を読んだ後の段。タグの `<名前`(閉じタグの `</名前` も)で開きタグの段に入り、`>` で出る。開きタグの中かどうかだけを
 * 持ち、要素の入れ子と本文の括弧は数えない(閉じタグを書かない要素があり、本文の括弧は色に効かない)。
 */
const htmlBracketsAfter = (brackets, token) => {
  if (isTagToken(TagName, token)) return TagLevels.OpeningTag;
  const closesOpeningTag = brackets === TagLevels.OpeningTag && token.value === ">";
  return closesOpeningTag ? Start.brackets : brackets;
};

/** 文法ごとの、字句を読んだ後の括弧と段の並び。 */
const bracketsAfterIn = (grammar) => {
  if (grammar.jsx === true) return jsxBracketsAfter;
  if (grammar.tags === true) return htmlBracketsAfter;
  return bracketsAfter;
};

/** 文法と段ごとの、字句を読む関数。 */
const tokenReaderOf = (grammar, bracket) => {
  if (grammar.tags === true) return htmlTokenAt;
  const readsJsx = grammar.jsx === true && isTagLevel(bracket);
  return readsJsx ? jsxTokenAt : tokenAt;
};

/**
 * HTML の字句。開きタグの中は文字列・属性名・引用符の無い属性の値を、それ以外はコメント・タグ・数値と語を読む(段は `cursor.bracket`)。
 * 本文の引用符は文字列を始めない(`Don't` の `'` から行末までを文字列にしない)。
 * @returns 字句。どれにも当たらなければ null(呼び出し側が 1 文字だけ進める)
 */
const htmlTokenAt = (cursor, grammar) => {
  if (cursor.bracket !== TagLevels.OpeningTag) {
    const tag = matchAt(TagName, cursor);
    if (tag) return Token("tok-kw", tag);
    return commentAt(cursor, grammar) || wordAt(cursor, grammar);
  }
  const quoted = stringAt(cursor, grammar);
  if (quoted) return quoted;
  const isUnquotedValue = cursor.prevSolid === "=";
  const word = matchAt(isUnquotedValue ? UnquotedAttributeValue : AttributeName, cursor);
  if (!word) return null;
  return Token(isUnquotedValue ? null : "tok-key", word);
};

// ファイルを 1 行目から読み進めたときの、各行の頭の埋め込み(`region`)と、最後の行を読み終えた後の埋め込み。
const regionsAlong = (path) => {
  const grammar = Tokenizer.grammarOf(path);
  const start = Tokenizer.startAfter(null, grammar);
  const carries = [start, ...Tokenizer.tokenizeLines(fs.readFileSync(path, "utf8").split("\n"), grammar, start).map((read) => read.carry)];
  return { heads: carries.slice(0, -1).map((carry) => carry.region), last: carries[carries.length - 1].region };
};
// 検査の開いた行から作った埋め込みが、1 行目から読み進めた埋め込みと食い違う行(1 始まり)。
const regionMismatchesOf = (path) => {
  const grammar = Tokenizer.grammarOf(path);
  const { heads } = regionsAlong(path);
  const isSame = (opening, index) => JSON.stringify(Tokenizer.startAfter(opening, grammar).region) === JSON.stringify(heads[index]);
  return checkerOpenings[path].flatMap((opening, index) => (isSame(opening, index) ? [] : [index + 1]));
};
// 行の終わりが、区切りの語(引用符で囲むなら閉じた引用符)の付いた `<<` で終わるか。

{
  label: "要素を読む拡張子の集合とヒアドキュメントを読む拡張子の集合は、どちらも解説の検査とページで同じ",
  actual: () => {
    const extensionsWhere = (reads) => Tokenizer.Extensions.filter((extension) => reads(Tokenizer.grammarOf(`a.${extension}`))).map((extension) => `.${extension}`).toSorted();
    return { elements: extensionsWhere((grammar) => grammar.tags === true), heredocs: extensionsWhere((grammar) => grammar.heredocs === true) };
  },
  expected: { elements: [...checkerExtensions.elements].sort(), heredocs: [...checkerExtensions.heredocs].sort() },
},

def read_blobs(names: set[str]) -> dict[str, bytes]:
    """blob の中身を、`git cat-file --batch` を 1 回だけ走らせて読む。

    名前は `ls-tree` が返した blob に限るので、読めないものがあればリポジトリのオブジェクトが欠けている。除いて続けると
    依存の辺が黙って消えるので、`UnreadableBlobError` で落とす(地図を半端に作らない)。

    @param names blob の名前
    @returns 名前 → 中身
    """
    ordered = sorted(names)
    contents = dict(zip(ordered, read_objects(ordered)))
    missing = [name for name, content in contents.items() if content is None]
    if missing:
        raise UnreadableBlobError(f"blob を読めない: {' '.join(missing)}")
    return contents

try:
    change_map = build_map(pr)
except subprocess.CalledProcessError as error:
    stderr = error.stderr.decode(errors="replace") if isinstance(error.stderr, bytes) else error.stderr
    print(f"git が失敗しました: {' '.join(error.cmd)}\n{stderr}", file=sys.stderr)
    return 1
except UnreadableBlobError as error:
    print(f"地図を作れません: {error}", file=sys.stderr)
    return 1
